cat << 'EOF' > /tmp/binlog-reader/Program.cs
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Check if there are other projects that failed due to dependency on Services
var projects = build.FindChildrenRecursive<Project>().ToList();
Console.WriteLine("=== ALL PROJECTS IN SOLUTION ===");
foreach (var p in projects)
{
    if (p.Name.EndsWith(".sln")) continue;
    var succeeded = !p.FindChildrenRecursive<Error>().Any();
    Console.WriteLine($"  {p.Name} - {(succeeded ? "OK" : "FAILED")}");
}

// Look at package references for Services.csproj
Console.WriteLine("\n=== LOOKING FOR PACKAGE REFERENCES IN Services.csproj ===");
var servicesProject = projects.FirstOrDefault(p => p.Name == "Services.csproj");
if (servicesProject != null)
{
    // Look for items/references
    var items = servicesProject.FindChildrenRecursive<Item>().Where(i => i.Text != null && i.Text.Contains("Newtonsoft")).ToList();
    Console.WriteLine($"Newtonsoft items found: {items.Count}");
    foreach (var item in items)
        Console.WriteLine($"  {item.Text}");

    // Check for restore warnings
    var warnings = servicesProject.FindChildrenRecursive<Warning>().ToList();
    Console.WriteLine($"\nWarnings in Services.csproj: {warnings.Count}");
    foreach (var w in warnings.Take(10))
        Console.WriteLine($"  {w.Code}: {w.Text}");

    // Look at all messages mentioning Newtonsoft or PackageReference
    var messages = servicesProject.FindChildrenRecursive<Message>().Where(m => m.Text != null && (m.Text.Contains("Newtonsoft") || m.Text.Contains("PackageReference"))).Take(10).ToList();
    Console.WriteLine($"\nMessages about Newtonsoft/PackageReference:");
    foreach (var m in messages)
        Console.WriteLine($"  {m.Text?.Substring(0, Math.Min(m.Text.Length, 200))}");
}

// Check for NU warnings anywhere
Console.WriteLine("\n=== NU WARNINGS (NuGet) ===");
var nuWarnings = build.FindChildrenRecursive<Warning>().Where(w => w.Code != null && w.Code.StartsWith("NU")).ToList();
foreach (var w in nuWarnings.Take(10))
    Console.WriteLine($"  {w.Code}: {w.Text}");
if (!nuWarnings.Any())
    Console.WriteLine("  (none)");
EOF
